  RK.extra(TR, '1.2', [['Which built-in group should hold only a handful of dedicated admin accounts?', 'Domain Admins', ['Domain Users', 'Authenticated Users', 'Guests'], 'Least privilege.'], ['Which group scope can contain members from any domain and grant access only in its own domain?', 'Domain Local', ['Global', 'Universal', 'Distribution'], 'DL.'], ['What happens to a user\'s access when their account is deleted and recreated?', 'It is lost — the new account has a new SID', ['It is kept', 'It doubles', 'It moves to Guest'], 'SID.'], ['Which cmdlet shows nested group members?', 'Get-ADGroupMember -Recursive', ['Get-ADUser -Nested', 'Get-ADGroup -All', 'whoami /groups'], 'Recursive.']]);
  RK.extra(TR, '2.1', [['Which cmdlet disables an account?', 'Disable-ADAccount', ['Set-ADUser -Disabled', 'Lock-ADAccount', 'Remove-ADUser'], 'Disable.'], ['Which TCP port does the AD PowerShell module use (AD Web Services)?', '9389', ['389', '5985', '445'], 'ADWS.'], ['Which is faster on a large domain?', 'Get-ADUser -Filter "Department -eq \'Sales\'"', ['Get-ADUser -Filter * | Where-Object Department -eq Sales', 'They are equal', 'Get-ADUser -Properties *'], 'Server-side.']]);
  RK.extra(TR, '2.2', [['Which cmdlet unlocks an account?', 'Unlock-ADAccount', ['Enable-ADAccount', 'Set-ADUser -Unlock', 'Reset-ADAccount'], 'Unlock.'], ['A lockout keeps returning after unlock. What is the usual cause?', 'A device still using the old password', ['Clock skew', 'DNS', 'Replication of GPOs'], 'Stale credential.'], ['Which command shows quick account status from any domain PC?', 'net user name /domain', ['net use name', 'ipconfig /user', 'klist name'], 'Status.']]);
  RK.extra(TR, '2.3', [['A user has Read via one group and Modify via another on the same folder (no Deny). Effective NTFS?', 'Modify', ['Read', 'No access', 'Full Control'], 'NTFS adds up.'], ['Which icacls code means Modify?', '(M)', ['(F)', '(RX)', '(W)'], 'Modify.'], ['What does (OI)(CI) mean in icacls output?', 'Inherited by files and subfolders', ['Owner and creator', 'Object integrity', 'Cached identity'], 'Inheritance.'], ['Who should get NTFS permissions on a share folder?', 'Domain Local groups', ['Individual users', 'Everyone with Full Control', 'Distribution groups'], 'AGDLP.']]);
  RK.extra(TR, '3.1', [['Where are the GPO template files stored?', 'SYSVOL', ['NTDS.dit', 'The registry of each client', 'C:\\Temp'], 'GPT.'], ['How often do DCs refresh Group Policy?', 'Every 5 minutes', ['Every 90 minutes', 'Daily', 'Never'], 'DCs.'], ['Which feature applies user settings based on the computer\'s OU?', 'Loopback processing', ['Block Inheritance', 'Enforced', 'WMI filter'], 'Loopback.']]);
  RK.extra(TR, '3.2', [['Which event ID is a Kerberos pre-authentication failure on the DC?', '4771', ['4740', '4624', '4769'], 'Pre-auth failed.'], ['Which logon type is RDP?', '10', ['2', '3', '5'], 'RemoteInteractive.'], ['Which command finds duplicate SPNs?', 'setspn -X', ['setspn -L', 'klist -d', 'nltest /spn'], 'Duplicates.']]);
  RK.extra(TR, '4.1', [['Which command shows FSMO role holders?', 'netdom query fsmo', ['repadmin /fsmo', 'dcdiag /roles', 'nltest /fsmo'], 'Roles.'], ['How long is the default inter-site replication interval?', '180 minutes', ['15 seconds', '24 hours', '5 minutes'], 'Site links.'], ['What must you never do after seizing a role from a failed DC?', 'Bring the old DC back online', ['Run repadmin', 'Back up the new holder', 'Check DNS'], 'Conflicts.']]);
  RK.extra(TR, '4.2', [['What is a gMSA?', 'A group Managed Service Account with automatic long random passwords', ['A guest account', 'A GPO type', 'A trust type'], 'Service accounts.'], ['Which group prevents members\' credentials from being cached and blocks NTLM/RC4?', 'Protected Users', ['Domain Users', 'Backup Operators', 'Remote Desktop Users'], 'Hardening.'], ['How many times should krbtgt be reset after a golden-ticket incident?', 'Twice', ['Once', 'Never', 'Ten times'], 'Two password history entries.']]);
  RK.cards(TR, '1.1', [['SRV records', 'How clients find DCs (_ldap._tcp.dc._msdcs).'], ['Forest', 'The real security boundary.'], ['NTDS.dit', 'Directory database with password hashes.']]);
  RK.cards(TR, '1.2', [['AGDLP', 'Accounts → Global → Domain Local → Permission.'], ['OU vs group', 'Location (GPO/delegation) vs access.'], ['Leaver', 'Disable → revoke → strip → move → delete later.']]);
  RK.cards(TR, '2.1', [['-Filter vs Where-Object', 'Server-side is far faster.'], ['-Properties', 'Request extra attributes.'], ['Bulk', 'Import-Csv | ForEach-Object { New-ADUser … } with -WhatIf.']]);
